(560662, 57201, 8488, '<td valign="top">Tarot isn''t zodiac, and vice-versa neither, I''m afraid. :-&gt; Tarot and astrology are completely separate divination paths.</td>', 'Tarot isn''t zodiac, and vice-versa neither, I''m afraid. :-> Tarot and astrology are completely separate divination paths.', '2004-01-28 12:53:57.000000', NULL, 1),
(560667, 57031, 8488, '<td valign="top">Disorientingly blurry, I''m afraid. If you''d downsized it a bit for sharpness, it could have been a much better picture, but as it is it looks like you were waving the camera around with the shutter open and makes me feel more seasick than anything else. :-&gt; Great colors and lighting, though.</td>', 'Disorientingly blurry, I''m afraid. If you''d downsized it a bit for sharpness, it could have been a much better picture, but as it is it looks like you were waving the camera around with the shutter open and makes me feel more seasick than anything else. :-> Great colors and lighting, though.', '2004-01-28 12:58:09.000000', NULL, 1),
(560695, 56641, 11206, '<td valign="top">This is great it almost looks like a lady in the water.  I love it. 10 for me.</td>', 'This is great it almost looks like a lady in the water.  I love it. 10 for me.', '2004-01-28 13:15:32.000000', NULL, 1),
