(560783, 57265, 11738, '<td valign="top">Top of the crawfish''s seems out of focus.  Interesting subject matter.  Not too crazy about that thin red line in the border: loses its intensity along quite a few spots around the edge of the image..  Plain black would have been better.</td>', 'Top of the crawfish''s seems out of focus.  Interesting subject matter.  Not too crazy about that thin red line in the border: loses its intensity along quite a few spots around the edge of the image..  Plain black would have been better.', '2004-01-28 14:05:12.000000', NULL, 1),
(560785, 57297, 14398, '<td valign="top">Excellent idea! Put together well.</td>', 'Excellent idea! Put together well.', '2004-01-28 14:06:36.000000', NULL, 1),
