(560792, 56848, 11738, '<td valign="top">Funky little goats.  Many white spots in their fur are overexposed.  Goat on left seems a bit out of focus</td>', 'Funky little goats.  Many white spots in their fur are overexposed.  Goat on left seems a bit out of focus', '2004-01-28 14:11:18.000000', NULL, 1),
(560802, 56927, 11738, '<td valign="top">Nice idea and composition, but the most important part of the shot, the statue''s eye, is out of focus.  Looks like the camera focussed on the edge of the mane instead.  I would have rather seen the tip of the nose to the eye in focus with the rest blurred by the DOF.  I like the lighting colour.  I would have also cropped out more of that "dead space" on the left.</td>', 'Nice idea and composition, but the most important part of the shot, the statue''s eye, is out of focus.  Looks like the camera focussed on the edge of the mane instead.  I would have rather seen the tip of the nose to the eye in focus with the rest blurred by the DOF.  I like the lighting colour.  I would have also cropped out more of that "dead space" on the left.', '2004-01-28 14:20:24.000000', NULL, 1),
(560815, 57261, 6130, '<td valign="top">Lovely and I like it a lot.</td>', 'Lovely and I like it a lot.', '2004-01-28 14:37:56.000000', NULL, 1),
