(561286, 57275, 15242, '<td valign="top">Pretty place to take pictures.  I think I would have cropped out the waterfall and just left the birds in the picture.</td>', 'Pretty place to take pictures.  I think I would have cropped out the waterfall and just left the birds in the picture.', '2004-01-28 20:46:13.000000', NULL, 1),
(561287, 57322, 3102, '<td valign="top">Might have been a little stronger if the bottom girl had taken her glasses off to emphasize the twins theme... but still quite nice.</td>', 'Might have been a little stronger if the bottom girl had taken her glasses off to emphasize the twins theme... but still quite nice.', '2004-01-28 20:47:39.000000', NULL, 1),
(561288, 57110, 15242, '<td valign="top">I like the concept and the thinking, but the result isn''t all that exciting.  I don''t like the use of the angle either.</td>', 'I like the concept and the thinking, but the result isn''t all that exciting.  I don''t like the use of the angle either.', '2004-01-28 20:47:49.000000', NULL, 1),
