(561294, 57268, 6179, '<td valign="top">Nice. Could have used a deeper DOF though.</td>', 'Nice. Could have used a deeper DOF though.', '2004-01-28 20:55:48.000000', NULL, 1),
(561295, 57272, 15242, '<td valign="top">Lighting on the lions are causing a little too much glare.  Did you try different angles?  I''d have probably tried to take the picture with only one lion in it, but that''s just me.</td>', 'Lighting on the lions are causing a little too much glare.  Did you try different angles?  I''d have probably tried to take the picture with only one lion in it, but that''s just me.', '2004-01-28 20:56:04.000000', NULL, 1),
