(561302, 56663, 14773, '<td valign="top">Very Very cool interpretation, if you hadn''t used this title I wouldn''t have known what it meant however. 6</td>', 'Very Very cool interpretation, if you hadn''t used this title I wouldn''t have known what it meant however. 6', '2004-01-28 21:01:54.000000', NULL, 1),
