(561406, 56784, 6532, '<td valign="top">Origianl idea.  Good colors.</td>', 'Origianl idea.  Good colors.', '2004-01-28 22:16:18.000000', NULL, 1),
(561409, 57217, 6600, '<td valign="top">Would probably work good for an eBay ad....  doesn''t make for an interesting photo though.  A bit hot in the top center, lacks composition.  Neat scale.</td>', 'Would probably work good for an eBay ad....  doesn''t make for an interesting photo though.  A bit hot in the top center, lacks composition.  Neat scale.', '2004-01-28 22:18:51.000000', NULL, 1),
(561412, 56722, 15026, '<td valign="top">He''s smiling at me, and I smiled back.  Nice shot.</td>', 'He''s smiling at me, and I smiled back.  Nice shot.', '2004-01-28 22:21:32.000000', NULL, 1),
(561418, 57324, 15026, '<td valign="top">Lighting is a little harsh</td>', 'Lighting is a little harsh', '2004-01-28 22:23:47.000000', NULL, 1),
(561422, 57217, 15026, '<td valign="top">Interesting subject - lighting is strong in the center, and in some of the reflections.  Undoubtedly, some detail has been lost in the size reduction, and that hurts this pic a bit.</td>', 'Interesting subject - lighting is strong in the center, and in some of the reflections.  Undoubtedly, some detail has been lost in the size reduction, and that hurts this pic a bit.', '2004-01-28 22:25:50.000000', NULL, 1),
(561427, 57323, 15026, '<td valign="top">You''ll probably get some low votes from the water drop haters, but I think it''s well done.  I was initially distracted by the background (towel?), but giving it a second chance, I think it adds something to the shot.  Nice symmetry - I wonder how an off-center crop would look?</td>', 'You''ll probably get some low votes from the water drop haters, but I think it''s well done.  I was initially distracted by the background (towel?), but giving it a second chance, I think it adds something to the shot.  Nice symmetry - I wonder how an off-center crop would look?', '2004-01-28 22:28:42.000000', NULL, 1),
(561431, 56828, 15026, '<td valign="top">Nice shot of the moon - some will certainly criticize as a subject over done....but it was probably fun to shoot.  I hope to take such a picture soon!</td>', 'Nice shot of the moon - some will certainly criticize as a subject over done....but it was probably fun to shoot.  I hope to take such a picture soon!', '2004-01-28 22:30:01.000000', NULL, 1),
(561438, 56275, 15026, '<td valign="top">Interesting to look at - necklace is distracting to me</td>', 'Interesting to look at - necklace is distracting to me', '2004-01-28 22:32:55.000000', NULL, 1),
(561444, 56275, 6600, '<td valign="top">This is very awesome!  Very neat way to incorporate a double exposure.  Love the color change and composition.  Exposure and focus very good. (One slight distraction is that red spot between the two images) - Excellent job!</td>', 'This is very awesome!  Very neat way to incorporate a double exposure.  Love the color change and composition.  Exposure and focus very good. (One slight distraction is that red spot between the two images) - Excellent job!', '2004-01-28 22:34:57.000000', NULL, 1),
(561446, 57218, 15026, '<td valign="top">Very nice.  Beautiful arc.  Nice exposure.  If someone gives you a low score, I hope they give a reason.</td>', 'Very nice.  Beautiful arc.  Nice exposure.  If someone gives you a low score, I hope they give a reason.', '2004-01-28 22:36:27.000000', NULL, 1),
