(564356, 56709, 14008, '<td valign="top">probably too abstract for some...</td>', 'probably too abstract for some...', '2004-02-01 12:33:48.000000', NULL, 1),
(564358, 57299, 14008, '<td valign="top">Great sunset and a nice example of how a simple single element in the foreground - the gull - can make all the difference between boring and interesting.</td>', 'Great sunset and a nice example of how a simple single element in the foreground - the gull - can make all the difference between boring and interesting.', '2004-02-01 12:35:59.000000', NULL, 1),
