(564700, 57306, 10768, '<td valign="top">Pretty cool picture.  It made me stop and really study it.  Nice composition</td>', 'Pretty cool picture.  It made me stop and really study it.  Nice composition', '2004-02-01 21:31:19.000000', NULL, 1),
(564701, 57110, 10768, '<td valign="top">Nice use of colors.</td>', 'Nice use of colors.', '2004-02-01 21:32:29.000000', NULL, 1),
(564703, 57261, 10768, '<td valign="top">Clear crisp image.  Nice composition.  Well done!</td>', 'Clear crisp image.  Nice composition.  Well done!', '2004-02-01 21:34:30.000000', NULL, 1),
(564704, 57122, 10768, '<td valign="top">I like the bold colors.  Nice sharp image.</td>', 'I like the bold colors.  Nice sharp image.', '2004-02-01 21:39:05.000000', NULL, 1),
(564707, 57230, 10768, '<td valign="top">I don''t get the representation with the phone, but I like this photo.  I really like the colors and lighting.  Good job!</td>', 'I don''t get the representation with the phone, but I like this photo.  I really like the colors and lighting.  Good job!', '2004-02-01 21:43:39.000000', NULL, 1),
(564708, 57297, 10768, '<td valign="top">Very funny.  I enjoyed the break after seeing so many photos of statues or figurines!</td>', 'Very funny.  I enjoyed the break after seeing so many photos of statues or figurines!', '2004-02-01 21:46:21.000000', NULL, 1),
(564710, 56722, 10768, '<td valign="top">I like how symetrical this photo with the goat looking straight at you.  I also think the use of B&amp;W is very effective.</td>', 'I like how symetrical this photo with the goat looking straight at you.  I also think the use of B&W is very effective.', '2004-02-01 21:47:56.000000', NULL, 1),
(564711, 57299, 10768, '<td valign="top">Very pretty capture.  The bird adds life to this photo.</td>', 'Very pretty capture.  The bird adds life to this photo.', '2004-02-01 21:49:16.000000', NULL, 1),
(564718, 56938, 10768, '<td valign="top">Good lighting.</td>', 'Good lighting.', '2004-02-01 22:31:57.000000', NULL, 1),
(564721, 57267, 10768, '<td valign="top">This is interesting and different.  Thank goodness it''s not another statue or figurine!  It almost has an eery feel to it.  I like it!</td>', 'This is interesting and different.  Thank goodness it''s not another statue or figurine!  It almost has an eery feel to it.  I like it!', '2004-02-01 22:38:07.000000', NULL, 1),
(564723, 57203, 10768, '<td valign="top">Love the colors and the lighting used.</td>', 'Love the colors and the lighting used.', '2004-02-01 22:41:31.000000', NULL, 1),
(564753, 57181, 6600, '<td valign="top">Slightly out of focus, glowing eyes distract, getting blown out by the flash.</td>', 'Slightly out of focus, glowing eyes distract, getting blown out by the flash.', '2004-02-01 23:52:17.000000', NULL, 1),
(564760, 57134, 6600, '<td valign="top">Good idea, but this shot seems a bit busy for me (to many focal points).  Also I feel the image is underexposed/oversaturated.</td>', 'Good idea, but this shot seems a bit busy for me (to many focal points).  Also I feel the image is underexposed/oversaturated.', '2004-02-01 23:55:38.000000', NULL, 1),
