INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(564767, 57322, 6600, '<td valign="top">Nice idea, good exposure, nice job.</td>', 'Nice idea, good exposure, nice job.', '2004-02-01 23:59:01.000000', NULL, 1),
(565219, 56641, 7543, '<td valign="top">Nice form, abstract. Good colors as well.</td>', 'Nice form, abstract. Good colors as well.', '2004-02-02 07:25:35.000000', NULL, 1),
(565265, 56726, 3087, '<td valign="top">Love this one! Crop/ close up is just right. High contrast really brings this to life. Excellent! 8</td>', 'Love this one! Crop/ close up is just right. High contrast really brings this to life. Excellent! 8', '2004-02-02 08:11:43.000000', NULL, 1),
(565267, 57184, 3087, '<td valign="top">Doesn''t link well to the theme for me but it''s certainly a beautiful image - very strong visually and I love the high contrast. 8</td>', 'Doesn''t link well to the theme for me but it''s certainly a beautiful image - very strong visually and I love the high contrast. 8', '2004-02-02 08:11:50.000000', NULL, 1),
(565268, 56709, 3087, '<td valign="top">A great abstract - the motion appears as brushstrokes in a surreal painting. I like the light and dark, the diagonal angles, the curves and curcles and sticks... 8</td>', 'A great abstract - the motion appears as brushstrokes in a surreal painting. I like the light and dark, the diagonal angles, the curves and curcles and sticks... 8', '2004-02-02 08:11:57.000000', NULL, 1),
(565270, 57188, 3087, '<td valign="top">Strong compositional balance, good use of DOF, lighting results in a good contrast between foreground and background without causing any loss in detail in the main subject. 8</td>', 'Strong compositional balance, good use of DOF, lighting results in a good contrast between foreground and background without causing any loss in detail in the main subject. 8', '2004-02-02 08:12:05.000000', NULL, 1),
(565271, 57230, 3087, '<td valign="top">Not sure I get the title nor the thought behind the phone but the photo itself really appeals on a visual level. I really like the browns of the crabs against the greys and blacks of the phone and background. Composition really is spot on. 8</td>', 'Not sure I get the title nor the thought behind the phone but the photo itself really appeals on a visual level. I really like the browns of the crabs against the greys and blacks of the phone and background. Composition really is spot on. 8', '2004-02-02 08:12:12.000000', NULL, 1),
(565272, 57159, 3087, '<td valign="top">He he he! I like the way you''re showing the human aspect of the zodiac - that it''s about predicting/ analysing human behaviour/ personalities. Very humourous, and strong composition. 8</td>', 'He he he! I like the way you''re showing the human aspect of the zodiac - that it''s about predicting/ analysing human behaviour/ personalities. Very humourous, and strong composition. 8', '2004-02-02 08:12:20.000000', NULL, 1),
(565273, 57321, 3087, '<td valign="top">Great composition - the lines from the folds and edges of the hands and fingers make a great pattern and the water looks great. Lighting seems to be a little brighter in the foreground though perhaps that''s because the low DOF blurs away the the shadows in the skin detail in the lower part of the frame. Black and white a good choice. 8</td>', 'Great composition - the lines from the folds and edges of the hands and fingers make a great pattern and the water looks great. Lighting seems to be a little brighter in the foreground though perhaps that''s because the low DOF blurs away the the shadows in the skin detail in the lower part of the frame. Black and white a good choice. 8', '2004-02-02 08:12:27.000000', NULL, 1),
(565274, 57306, 3087, '<td valign="top">This is soooooooooooooooooo clever! I have never seen an image like this! I''m not sure the image itself is particularly pleasing aesthetically but the content is so fascinating that it compensates! 8</td>', 'This is soooooooooooooooooo clever! I have never seen an image like this! I''m not sure the image itself is particularly pleasing aesthetically but the content is so fascinating that it compensates! 8', '2004-02-02 08:12:34.000000', NULL, 1),
(565276, 56927, 3087, '<td valign="top">Nice choice of subject, especially when only a portion of the detail is presented like this. Nice composition, nice use of shallow DOF. 8</td>', 'Nice choice of subject, especially when only a portion of the detail is presented like this. Nice composition, nice use of shallow DOF. 8', '2004-02-02 08:12:41.000000', NULL, 1),
(565280, 57297, 3087, '<td valign="top">Very cool how the water bottle catches the light - it looks as though he''s carrying the sun itself.<br/>Big shame about the butt crack - I could do without seeing that!<br/></td>', 'Very cool how the water bottle catches the light - it looks as though he''s carrying the sun itself.Big shame about the butt crack - I could do without seeing that!', '2004-02-02 08:13:28.000000', NULL, 1),
(565296, 57159, 16676, '<td valign="top">Doesn''t really look bullish to me. Maybe a different expression and angle would have helped.</td>', 'Doesn''t really look bullish to me. Maybe a different expression and angle would have helped.', '2004-02-02 08:28:24.000000', NULL, 1),
(565297, 56722, 9941, '<td valign="top">Humourous!  Nice photo!</td>', 'Humourous!  Nice photo!', '2004-02-02 08:29:30.000000', NULL, 1),
