(566643, 57030, 12733, '<td valign="top">Cute idea, nicely rendered. Great detail on the crab''s face and claws.</td>', 'Cute idea, nicely rendered. Great detail on the crab''s face and claws.', '2004-02-03 06:39:59.000000', NULL, 1),
(566644, 57307, 12733, '<td valign="top">Nice lighting and rendering. I thought it was a real fish at first, but now I''m not so sure. The reflection looks more like glass or porcelain that the texture of a fish''s body.</td>', 'Nice lighting and rendering. I thought it was a real fish at first, but now I''m not so sure. The reflection looks more like glass or porcelain that the texture of a fish''s body.', '2004-02-03 06:42:40.000000', NULL, 1),
(566645, 57275, 15832, '<td valign="top">Really nice.Hope this photo is gonna win. Could maby be littel more brighter but non the less the best photo so far.... The  moment capture couldn´t be better.perfekt location,So alive   (10)</td>', 'Really nice.Hope this photo is gonna win. Could maby be littel more brighter but non the less the best photo so far.... The  moment capture couldn´t be better.perfekt location,So alive   (10)', '2004-02-03 06:45:43.000000', NULL, 1),
(566646, 57264, 12733, '<td valign="top">Poor Taurus! Nice rendering, but the lighting seems a bit flat, like a flash on camera alone.</td>', 'Poor Taurus! Nice rendering, but the lighting seems a bit flat, like a flash on camera alone.', '2004-02-03 06:45:51.000000', NULL, 1),
(566648, 57275, 12733, '<td valign="top">Brilliant capture. When you get composition, sharpness and a background this good, the blur in the wing tips is acceptable. I really like this shot.</td>', 'Brilliant capture. When you get composition, sharpness and a background this good, the blur in the wing tips is acceptable. I really like this shot.', '2004-02-03 06:47:48.000000', NULL, 1),
(566649, 57305, 12733, '<td valign="top">Cute closeup, but the focus is too soft.</td>', 'Cute closeup, but the focus is too soft.', '2004-02-03 06:48:12.000000', NULL, 1),
(566650, 56800, 12733, '<td valign="top">Interesting lighting and composition, but kind of a stretch to meet the challenge.</td>', 'Interesting lighting and composition, but kind of a stretch to meet the challenge.', '2004-02-03 06:49:22.000000', NULL, 1),
(566651, 56988, 12733, '<td valign="top">Nice composition, and great exposure on the grass. The bull needs more detail; he''s gone almost completely black without texture or even features beyond the eyes.</td>', 'Nice composition, and great exposure on the grass. The bull needs more detail; he''s gone almost completely black without texture or even features beyond the eyes.', '2004-02-03 06:51:34.000000', NULL, 1),
(566653, 56650, 12733, '<td valign="top">A very cute photo, and nicely lit and composed.</td>', 'A very cute photo, and nicely lit and composed.', '2004-02-03 06:52:41.000000', NULL, 1),
(566654, 57076, 15832, '<td valign="top">This photo is really calm and relaxing.  The water drops makes it so fresh and young</td>', 'This photo is really calm and relaxing.  The water drops makes it so fresh and young', '2004-02-03 06:53:05.000000', NULL, 1),
(566655, 56780, 12733, '<td valign="top">I like the jug and the pose. They give the photo a classic look that goes well with the theme.</td>', 'I like the jug and the pose. They give the photo a classic look that goes well with the theme.', '2004-02-03 06:55:29.000000', NULL, 1),
(566656, 57087, 12733, '<td valign="top">I think stars would say zodiac more that a cloudy daytime sky.</td>', 'I think stars would say zodiac more that a cloudy daytime sky.', '2004-02-03 06:57:07.000000', NULL, 1),
(566660, 56575, 12733, '<td valign="top">I find the lighting on this photo espcially interesting, and the composition is pleasing. I think the tight crop works very well.</td>', 'I find the lighting on this photo espcially interesting, and the composition is pleasing. I think the tight crop works very well.', '2004-02-03 06:58:42.000000', NULL, 1),
(566662, 57030, 15832, '<td valign="top">That would look great on my kitchen wall. Proffesional work indeed. good job (8)</td>', 'That would look great on my kitchen wall. Proffesional work indeed. good job (8)', '2004-02-03 07:00:29.000000', NULL, 1),
(566663, 57047, 12733, '<td valign="top">Great detail, and I like the expression on the lion''s face.</td>', 'Great detail, and I like the expression on the lion''s face.', '2004-02-03 07:00:33.000000', NULL, 1),
(566665, 57265, 15832, '<td valign="top">Looks like a shrimp ;)  good contrast.</td>', 'Looks like a shrimp ;)  good contrast.', '2004-02-03 07:01:50.000000', NULL, 1),
