(566678, 57251, 15832, '<td valign="top">Good mixture...</td>', 'Good mixture...', '2004-02-03 07:17:40.000000', NULL, 1),
(566686, 57324, 12733, '<td valign="top">I like the idea, but without showing where the water is going, it seems as though he''s just dumping it on the floor.</td>', 'I like the idea, but without showing where the water is going, it seems as though he''s just dumping it on the floor.', '2004-02-03 07:23:16.000000', NULL, 1),
