(566689, 56428, 12733, '<td valign="top">This is certainly a different interpretation of "balance" from the usual scales that Libra is supposed to stand for. It''s a nice closeup, but the point of sharpest focus seems to be the branch, rather than the grasshopper''s head.</td>', 'This is certainly a different interpretation of "balance" from the usual scales that Libra is supposed to stand for. It''s a nice closeup, but the point of sharpest focus seems to be the branch, rather than the grasshopper''s head.', '2004-02-03 07:27:46.000000', NULL, 1),
(566690, 56848, 12733, '<td valign="top">This is a cute pair of goats. The detail on the white goat is especially good, as this color of animal is hard to render.</td>', 'This is a cute pair of goats. The detail on the white goat is especially good, as this color of animal is hard to render.', '2004-02-03 07:31:05.000000', NULL, 1),
(566691, 56722, 11241, '<td valign="top">Very well framed. and great DOF.....9</td>', 'Very well framed. and great DOF.....9', '2004-02-03 07:31:11.000000', NULL, 1),
(566692, 57304, 12733, '<td valign="top">I like the rendering of the water; you can see some detail while the sense of a steady stream remains. The lighting is interesting.</td>', 'I like the rendering of the water; you can see some detail while the sense of a steady stream remains. The lighting is interesting.', '2004-02-03 07:33:50.000000', NULL, 1),
(566693, 57110, 12733, '<td valign="top">The symbolism is interesting, but kind of obscure. I do like the textures, lighting and composition.</td>', 'The symbolism is interesting, but kind of obscure. I do like the textures, lighting and composition.', '2004-02-03 07:35:35.000000', NULL, 1),
