(566695, 57289, 12733, '<td valign="top">These are beautifully rendered lions. Is this their real background? Is the background color actual or altered in post processing?</td>', 'These are beautifully rendered lions. Is this their real background? Is the background color actual or altered in post processing?', '2004-02-03 07:38:06.000000', NULL, 1),
(566696, 57218, 12733, '<td valign="top">Spectacular light - was it accomplished by moving the light source? An interesting composition.</td>', 'Spectacular light - was it accomplished by moving the light source? An interesting composition.', '2004-02-03 07:39:46.000000', NULL, 1),
(566698, 57181, 12733, '<td valign="top">Cute cat, but the focus is way too soft and the eyes are burnt out.</td>', 'Cute cat, but the focus is way too soft and the eyes are burnt out.', '2004-02-03 07:40:39.000000', NULL, 1),
