(567451, 57201, 6600, '<td valign="top">I think it''s a challenge to make an interesting photo from a two dimensional subject.  This shot is flat, lacking range or depth, a little lack-luster for me.</td>', 'I think it''s a challenge to make an interesting photo from a two dimensional subject.  This shot is flat, lacking range or depth, a little lack-luster for me.', '2004-02-03 22:21:01.000000', NULL, 1),
(567452, 56711, 16052, '<td valign="top">I like the concept.  Good use of blurred background to convey movement.</td>', 'I like the concept.  Good use of blurred background to convey movement.', '2004-02-03 22:21:37.000000', NULL, 1),
(567453, 57274, 16052, '<td valign="top">Hand appears overly red saturated.  Lighting could have been improved.</td>', 'Hand appears overly red saturated.  Lighting could have been improved.', '2004-02-03 22:23:05.000000', NULL, 1),
(567456, 57251, 6600, '<td valign="top">Probably trying to create a dreamy image, but this is a little to soft for my tastes.  Is the face a tad overexposed?</td>', 'Probably trying to create a dreamy image, but this is a little to soft for my tastes.  Is the face a tad overexposed?', '2004-02-03 22:24:22.000000', NULL, 1),
